function plot_results(cfg, slots, ripp_results, tqdo_results)
%PLOT_RESULTS Produce PNG comparisons between RIPP-DR and TQDO outputs.
%   PLOT_RESULTS(cfg, slots, ripp_results, tqdo_results) expects the per-slot
%   KPI arrays generated by the simulators. `slots` is a numeric vector of slot
%   indices. The function writes three PNG files inside cfg.Output.dir:
%     - miss_rt.png : RT miss-rate comparison
%     - util.png    : RU/DU/CU utilization comparison
%     - cost.png    : SP cost comparison

arguments
    cfg struct
    slots (:,1) double
    ripp_results (:,1) struct
    tqdo_results (:,1) struct
end

out_dir = cfg.Output.dir;
if ~exist(out_dir, 'dir') %#ok<EXIST>
    mkdir(out_dir);
end

miss_ripp = [ripp_results.miss_rt_rate]';
miss_tqdo = [tqdo_results.miss_rt_rate]';

fig1 = figure('Visible','off');
plot(slots, miss_ripp, '-o', 'DisplayName', 'RIPP-DR'); hold on;
plot(slots, miss_tqdo, '-s', 'DisplayName', 'TQDO');
xlabel('Slot index'); ylabel('RT miss rate');
title('RT Miss Probability per Slot');
ylim([0, 1]); grid on; legend('Location','best');
saveas(fig1, fullfile(out_dir, 'miss_rt.png'));
close(fig1);

util_ru_ripp = [ripp_results.util_ru]';
util_du_ripp = [ripp_results.util_du]';
util_cu_ripp = [ripp_results.util_cu]';
util_ru_tqdo = [tqdo_results.util_ru]';
util_du_tqdo = [tqdo_results.util_du]';
util_cu_tqdo = [tqdo_results.util_cu]';

fig2 = figure('Visible','off');
subplot(3,1,1);
plot(slots, util_ru_ripp, '-o', slots, util_ru_tqdo, '-s');
ylabel('RU util'); ylim([0,1]); grid on; legend('RIPP-DR','TQDO');

subplot(3,1,2);
plot(slots, util_du_ripp, '-o', slots, util_du_tqdo, '-s');
ylabel('DU util'); ylim([0,1]); grid on;

subplot(3,1,3);
plot(slots, util_cu_ripp, '-o', slots, util_cu_tqdo, '-s');
xlabel('Slot index'); ylabel('CU util'); ylim([0,1]); grid on;

sgtitle('Resource Utilization');
saveas(fig2, fullfile(out_dir, 'util.png'));
close(fig2);

cost_ripp = [ripp_results.cost_sp]';
cost_tqdo = [tqdo_results.cost_sp]';

fig3 = figure('Visible','off');
plot(slots, cost_ripp, '-o', 'DisplayName', 'RIPP-DR'); hold on;
plot(slots, cost_tqdo, '-s', 'DisplayName', 'TQDO');
xlabel('Slot index'); ylabel('SP cost [currency]');
title('Per-Slot Service-Provider Cost');
grid on; legend('Location','best');
saveas(fig3, fullfile(out_dir, 'cost.png'));
close(fig3);
end
